"""Validate generated bytes before publishing a success record."""
from pathlib import Path
from hashlib import sha256
from pypdf import PdfReader
from datetime import datetime, timezone
from zipfile import ZipFile
from xml.etree import ElementTree


def validate_pdf(path: Path) -> dict:
    if not path.is_file():
        raise ValueError('Document worker produced no file')
    data = path.read_bytes()
    if not data.startswith(b'%PDF-'):
        raise ValueError('Document worker produced invalid PDF bytes')
    reader = PdfReader(path, strict=True)
    if not reader.pages:
        raise ValueError('Document worker produced an empty PDF')
    return {'validationStatus': 'validated', 'validatedAt': datetime.now(timezone.utc).isoformat(),
            'canonicalPath': str(path.resolve()), 'sha256': sha256(data).hexdigest(),
            'fileSizeBytes': len(data), 'pageCount': len(reader.pages)}


def validate_document(path: Path, fmt: str) -> dict:
    if fmt == 'pdf':
        return validate_pdf(path)
    data = path.read_bytes()
    if not data:
        raise ValueError('Empty document')
    if fmt in {'docx', 'pptx'}:
        with ZipFile(path) as archive:
            if archive.testzip():
                raise ValueError('Corrupt document archive')
            main = 'word/document.xml' if fmt == 'docx' else 'ppt/presentation.xml'
            ElementTree.fromstring(archive.read(main))
    else:
        data.decode('utf-8')
    return {'validationStatus': 'validated', 'validatedAt': datetime.now(timezone.utc).isoformat(),
            'canonicalPath': str(path.resolve()), 'sha256': sha256(data).hexdigest(), 'fileSizeBytes': len(data)}
